import React from 'react';
import { motion } from 'framer-motion';
import { Lock, User, ShieldCheck, ArrowRight } from 'lucide-react';

const Login = () => {
  return (
    <div className="min-h-screen w-full flex items-center justify-center relative overflow-hidden bg-blue-linen">
      {/* BACKGROUND EFFECTS: Animated Glow Orbs */}
      <div className="absolute top-[-10%] left-[-10%] w-[500px] h-[500px] rounded-full bg-sungold/20 blur-[120px] animate-pulse" />
      <div className="absolute bottom-[-10%] right-[-10%] w-[500px] h-[500px] rounded-full bg-seed-green/20 blur-[120px] animate-pulse" />

      {/* MAIN LOGIN CARD */}
      <motion.div 
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8, ease: "easeOut" }}
        className="relative z-10 w-full max-w-md p-10 mx-4 rounded-[2.5rem] border border-white/40 shadow-2xl backdrop-blur-xl bg-white/30"
      >
        {/* LOGO SECTION */}
        <div className="text-center mb-10">
          <motion.div 
            initial={{ scale: 0, rotate: -20 }}
            animate={{ scale: 1, rotate: 3 }}
            transition={{ delay: 0.2, type: "spring", stiffness: 200 }}
            className="w-20 h-20 bg-sungold rounded-3xl mx-auto mb-6 flex items-center justify-center shadow-lg shadow-sungold/40"
          >
            <ShieldCheck size={42} className="text-butter-bean" />
          </motion.div>

          <h1 className="text-4xl font-black text-grassy-green tracking-tight">
            ADMIN<span className="text-sungold">.</span>
          </h1>
          <p className="text-grassy-green/70 mt-2 font-medium tracking-wide uppercase text-xs">
            Eco-System Control Center
          </p>
        </div>

        {/* FORM SECTION */}
        <form className="space-y-5" onSubmit={(e) => e.preventDefault()}>
          <div className="space-y-1">
            <label className="text-xs font-bold text-grassy-green uppercase ml-2 tracking-widest">Administrator ID</label>
            <div className="relative group">
              <User className="absolute left-4 top-1/2 -translate-y-1/2 text-grassy-green/40 group-focus-within:text-sungold transition-colors" size={20} />
              <input 
                type="email" 
                placeholder="admin@eco.com"
                className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white/50 border border-white/20 focus:border-sungold/50 focus:bg-white/80 outline-none transition-all text-grassy-green placeholder:text-grassy-green/30 font-medium"
              />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-xs font-bold text-grassy-green uppercase ml-2 tracking-widest">Security Key</label>
            <div className="relative group">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-grassy-green/40 group-focus-within:text-sungold transition-colors" size={20} />
              <input 
                type="password" 
                placeholder="••••••••"
                className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white/50 border border-white/20 focus:border-sungold/50 focus:bg-white/80 outline-none transition-all text-grassy-green placeholder:text-grassy-green/30 font-medium"
              />
            </div>
          </div>

          <motion.button
            whileHover={{ scale: 1.02, boxShadow: "0 20px 25px -5px rgb(255 91 3 / 0.4)" }}
            whileTap={{ scale: 0.98 }}
            className="w-full py-4 mt-4 bg-sungold text-white font-black rounded-2xl shadow-xl flex items-center justify-center gap-3 group transition-all"
          >
            INITIALIZE SESSION
            <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform" />
          </motion.button>
        </form>

        {/* FOOTER ACCENT */}
        <div className="mt-10 flex justify-center items-center gap-4">
          <div className="h-[1px] w-12 bg-grassy-green/10"></div>
          <span className="text-[10px] text-grassy-green/40 font-bold uppercase tracking-[0.2em]">Tier-1 Encryption</span>
          <div className="h-[1px] w-12 bg-grassy-green/10"></div>
        </div>
      </motion.div>

      {/* DECORATIVE ACCENT: Butter Bean Bottom Strip */}
      <div className="absolute bottom-0 w-full h-1 bg-gradient-to-r from-transparent via-butter-bean to-transparent opacity-50" />
    </div>
  );
};

export default Login;
